          {
            "heading": "Vælg Sungold hvis",
            "items": [
              "du vil have orange frugter og meget høj sødme",
              "du prioriterer en særlig tidlig snacktomat",
              "du accepterer, at modne frugter lettere revner"
            ]
          }
